"""Volume-two reviews: original summaries, separate extensions and open writing."""
from gen_overview import gen_sheet, box
from english.units import label


def sheet(unit,content):
    col,bg='#A63C70','#FFE4F0'
    pictures='<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,240px),1fr));gap:20px">'+''.join('<figure style="margin:0;min-width:0">'+content.picture(w,280)+f'<figcaption style="font-weight:700;margin-top:8px">{w}</figcaption></figure>' for w in content.CORE)+'</div>'
    def lesson(n,title,pg,head,body):return dict(n=n,title=title,pg=pg,head=head,body=lambda c:body,col=col,bg=bg,dk='#702344')
    if unit['n']=='R3':
        lessons=[
            lesson(1,'Chuyện đã qua và kế hoạch mới','36–37','Ôn Units 11–13: đúng mốc thời gian và loại thông tin.',pictures+box(bg,'<b>Did you take photos?</b> — Yes, I did. I took photos.<br><b>Will you decorate the house at Tet?</b> — Yes, I will.<br><b>Where will you go at Tet?</b> — I will go to the flower festival.<br><b>What food / drinks will you have?</b> — We will have pizza and apple juice.')+box(bg,'<b>Did + nguyên mẫu</b>; câu kể quá khứ: took, bought, collected.<br><b>Will + nguyên mẫu</b>: will make, will have; không will makes/has.<br>Đọc đúng người, last weekend và next week; không lấy kế hoạch thay cho việc đã làm.')),
            lesson(2,'Thói quen và lời thoại quan tâm','36–37','Ôn Units 14–15: How often khác What is the matter.',box(bg,'<b>How does he stay healthy?</b> — He plays sports.<br><b>How often does he play sports?</b> — Twice a week.<br><b>What is the matter?</b> — I have a headache.<br><b>What should I do?</b> — You should have a rest.')+box(bg,'He/she + plays/does; câu hỏi does…play/do. Should + nguyên mẫu.<br>Lời khuyên trong đề lấy theo thẻ hội thoại giả định; không suy triệu chứng thành một đáp án duy nhất. Nếu bé đang không khỏe, báo người lớn.')),
            lesson(3,'Đọc, viết và Extension riêng','37–39','Tự kể ngày lễ, rồi khám phá tên nhóm thực phẩm.',box(bg,'<b>Thử viết khoảng 40 từ về một ngày Trung thu đã qua:</b> khi nào, ở đâu, em đã làm gì, đã ăn/uống gì?<br><b>Thẻ mẫu tự soạn:</b> Last September · at school · watched a show · had mooncakes and apple juice.<br><b>Gợi ý mở đầu:</b> Last September, I celebrated the Mid-Autumn Festival at school.<br>Đây là luyện viết mở với người thân; đề tự chấm dùng thẻ và yêu cầu cụ thể.')+box(bg,'<b>Extension trang 38–39:</b> dairy — nhóm sữa; grains — ngũ cốc; protein — nhóm thực phẩm giàu đạm; fruit and vegetables — trái cây và rau.<br><b>Thẻ học từ:</b> milk → dairy; rice → grains; fish → protein; carrot → fruit and vegetables.<br>Thử viết/vẽ bữa sáng em thích rồi nói với người thân; không yêu cầu món giống nhau cho mọi bé.'))]
        number=3;scope='11–15';chips=['Chuyến đi và kế hoạch','Thói quen và lời thoại','Đọc viết · Extension']
    else:
        lessons=[
            lesson(1,'Thời tiết, trang phục và truyện','70–71','Ôn Units 16–17: đọc dữ kiện, giữ đúng dạng động từ.',pictures+box(bg,'<b>How is the weather?</b> — It is cool and windy.<br><b>What do you usually wear?</b> — I usually wear a jumper and trousers.<br><b>Who is the main character?</b> — The tortoise.<br><b>How did it walk?</b> — It walked slowly.')+box(bg,'Sau do/did dùng wear/walk; câu kể quá khứ dùng walked/ran.<br>Thời tiết theo thẻ, không mặc định một mùa giống nhau ở mọi nơi. Truyện tự soạn có đủ dữ kiện, không cần thuộc truyện bên ngoài.')),
            lesson(2,'Nơi đến, phương tiện và kỳ nghỉ','70–71','Ôn Units 18–20: mỗi câu hỏi lấy đúng một loại thông tin.',box(bg,'<b>Where do you want to visit?</b> — I want to visit the lake.<br><b>How can I get there?</b> — You can get there by bus.<br><b>How far is it?</b> — It is five kilometres.<br><b>What do you think of the lake?</b> — I think it is peaceful.<br><b>What are you going to do this summer?</b> — I am going to go camping.')+box(bg,'Can + get; by bus / <b>on foot</b>; from…to…<br>It is với một nơi, they are với nhiều nơi. I am / she is / they are going to + nguyên mẫu.<br>Bản đồ, khoảng cách và kế hoạch trong đề là giả định; ý kiến khác nhau theo từng người.')),
            lesson(3,'Viết kỳ nghỉ và Extension riêng','71–73','Ghép thông tin chuyến đi rồi giới thiệu truyện em thích.',box(bg,'<b>Thử viết khoảng 40 từ về kỳ nghỉ:</b> nơi sẽ đến, khoảng cách, phương tiện, việc sẽ làm, cảm nhận.<br><b>Thẻ tự soạn:</b> the lake · five kilometres · by bus · go camping · peaceful.<br><b>Viết theo thẻ:</b> I am going to visit the lake. It is five kilometres away. I can get there by bus. I am going to go camping. I think it is peaceful.<br>Nhờ người thân đọc cùng; website chưa chấm bài luận tự do.')+box(bg,'<b>Extension trang 72–73:</b> adventure story — truyện phiêu lưu; mystery story — truyện bí ẩn/trinh thám; history story — truyện lịch sử; spooky story — truyện có yếu tố ma quái.<br><b>I like adventure stories because I think they are exciting.</b><br>Thể loại lấy theo nhãn thẻ; sở thích/lý do là của em. Chọn truyện thấy thoải mái rồi kể cho người thân.'))]
        number=4;scope='16–20';chips=['Thời tiết và truyện','Chuyến đi và kế hoạch','Đọc viết · Extension']
    result=gen_sheet(number,'ÔN TẬP UNIT '+scope,f"{label(unit)} · Global Success 5 · Tập hai · Trang {unit['pages']}",col,bg,lessons,chips,'Ghép những điều đã học, tự tin thêm từng chút.','Sáu đề, nghe ba mức và trang học từ/phát âm; tiến độ lưu trên trình duyệt của em.',f"Nội dung tự soạn, bám {label(unit)} · Global Success 5, tập hai")
    return result.replace('>Chủ đề</span>','>Review</span>',1)
